          if [ "$(sha256sum "$ODIR/office-server.py" | cut -d' ' -f1)" != "7a9c3f0342026294bfe39f3226fc92d04b77be78a39822bb9286a246e30f11f7" ]; then echo "   File del servizio Office non integro: saltato."
          else
            $SUDO chmod 755 "$ODIR"; $SUDO chmod 644 "$ODIR/office-server.py"
            if [ ! -s "$KDIR/office.key" ]; then
              head -c 24 /dev/urandom | od -An -tx1 | tr -d ' \n' | $SUDO tee "$KDIR/office.key" >/dev/null
              $SUDO chown 1000:1000 "$KDIR/office.key" 2>/dev/null || true; $SUDO chmod 600 "$KDIR/office.key"
            fi
            OIMG="giot-office:1"
            if ! $SUDO docker image inspect "$OIMG" >/dev/null 2>&1; then
              echo "   Preparo il servizio Office (la prima volta scarica LibreOffice: 5-10 minuti, una volta sola)"
              OBD=$(mktemp -d)
              cat > "$OBD/Dockerfile" <<'DF'
FROM ubuntu:24.04
ENV DEBIAN_FRONTEND=noninteractive
RUN apt-get update && apt-get install -y --no-install-recommends libreoffice-writer-nogui libreoffice-calc-nogui python3-minimal fonts-liberation fonts-dejavu-core fonts-crosextra-carlito fonts-crosextra-caladea ca-certificates procps && rm -rf /var/lib/apt/lists/*
DF
              $SUDO timeout 1500 docker build -q -t "$OIMG" "$OBD" >/dev/null 2>&1 || echo "   Costruzione del servizio Office non riuscita."
              rm -rf "$OBD"
            fi
            if $SUDO docker image inspect "$OIMG" >/dev/null 2>&1; then
              $SUDO docker rm -f giot-office >/dev/null 2>&1 || true
              if $SUDO docker run -d --name giot-office --restart unless-stopped --network host --read-only --tmpfs /tmp:size=384m \
                   --log-opt max-size=10m --log-opt max-file=3 --cap-drop ALL --security-opt no-new-privileges --memory 1g --pids-limit 200 --user 1000:1000 \
                   -e OFFICE_PORT=3003 -e OFFICE_BIND=127.0.0.1 -e OFFICE_KEY="$($SUDO cat "$KDIR/office.key")" \
                   -v "$ODIR":/app:ro "$OIMG" python3 /app/office-server.py >/dev/null 2>&1; then
                OFFICE_ENV="-e OFFICE_URL=http://127.0.0.1:3003 -e OFFICE_KEY_FILE=/key/office.key"
                echo "   Servizio Office attivo (solo su questa macchina, 127.0.0.1:3003)."
              else echo "   Servizio Office non avviato: i .doc useranno la copia semplificata."; fi
            else echo "   Servizio Office non disponibile: i .doc useranno la copia semplificata."; fi
          fi
        fi
        $SUDO docker rm -f giot-fetch >/dev/null 2>&1 || true
        if $SUDO docker run -d --name giot-fetch --restart unless-stopped --network host --read-only --tmpfs /tmp \
             --log-opt max-size=10m --log-opt max-file=3 --cap-drop ALL --security-opt no-new-privileges --memory 384m --pids-limit 64 --user node \
             -e PORT=3002 -e BIND=127.0.0.1 -e AUTH_BASE=http://127.0.0.1:3001 -e DATA_DIR=/data -e VAULT_KEY_FILE=/key/vault.key $OFFICE_ENV \
             -v "$FDIR":/app:ro -v "$FDATA":/data -v "$KDIR":/key:ro node:22-alpine node /app/server.mjs >/dev/null 2>&1; then started=1
        else echo "   Docker non è riuscito ad avviarlo."; fi
      fi
    fi
    if [ "$started" = 0 ] && { [ "$FETCH_MODE" = auto ] || [ "$FETCH_MODE" = systemd ]; } \
       && command -v node >/dev/null 2>&1 && command -v systemctl >/dev/null 2>&1 \
       && node -e 'process.exit(+process.versions.node.split(".")[0] >= 18 ? 0 : 1)'; then
      $SUDO tee /etc/systemd/system/giot-fetch.service >/dev/null <<UNIT
[Unit]
Description=giot-fetch (lettore di pagine web per la chat)
After=network-online.target
[Service]
ExecStart=$(command -v node) $FDIR/server.mjs
Environment=PORT=3002 BIND=127.0.0.1 AUTH_BASE=http://127.0.0.1:3001 DATA_DIR=/var/lib/giot-fetch VAULT_KEY_FILE=/var/lib/giot-fetch-key/vault.key
StateDirectory=giot-fetch giot-fetch-key
StateDirectoryMode=0700
DynamicUser=yes
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
MemoryMax=192M
Restart=always
RestartSec=3
[Install]
WantedBy=multi-user.target
UNIT
      if $SUDO systemctl daemon-reload && $SUDO systemctl enable --now giot-fetch >/dev/null 2>&1; then started=1; fi
    fi
    if [ "$started" = 1 ] && fetch_health; then
      FETCH_UP=1; echo "   Lettore attivo (solo su questa macchina, 127.0.0.1:3002)."
      echo "   Archivio clienti: dati cifrati in $FDATA/vault; la CHIAVE è in $KDIR/vault.key (copiala in un posto sicuro: senza chiave le copie non si leggono)."
    else
      echo "   Lettore NON attivo: la chat funziona, ma la lettura delle pagine resta spenta."
    fi
  fi
fi

echo "5/7 Aggiorno la configurazione di Caddy (copia di sicurezza inclusa)"
BAK="$CF.bak-chat-$(date +%F-%H%M%S)"
$SUDO cp "$CF" "$BAK"
$SUDO env CF="$CF" HOST="$HOST" DEST="$DEST" FETCH_UP="$FETCH_UP" python3 - <<'PY'
import os, re
cf, host, dest = os.environ['CF'], os.environ['HOST'], os.environ['DEST']
fetch = '\thandle_path /fetch/* {\n\t\treverse_proxy 127.0.0.1:3002\n\t}\n' if os.environ.get('FETCH_UP') == '1' else ''
s = open(cf).read()
m = re.search(r'(?m)^' + re.escape(host) + r'\s*\{', s)
if m:
    i = m.end(); depth = 1
    while i < len(s) and depth:
        depth += {'{': 1, '}': -1}.get(s[i], 0); i += 1
    s = (s[:m.start()] + s[i:]).rstrip() + '\n'
block = f"""
{host} {{
	redir /chat /chat/
	handle_path /chat/* {{
		root * {dest}
		header Cache-Control "no-cache"
		file_server
	}}
{fetch}	handle {{
		reverse_proxy 127.0.0.1:3001
	}}
}}
"""
open(cf, 'w').write(s.rstrip() + '\n' + block)
PY

echo "6/7 Controllo la configurazione"
if command -v caddy >/dev/null 2>&1; then
  if ! $SUDO caddy validate --config "$CF" --adapter caddyfile >/dev/null 2>&1; then
    echo "Configurazione non valida: ripristino la copia di sicurezza."
    $SUDO cp "$BAK" "$CF"; exit 1
  fi
  echo "   Configurazione valida."
  echo "7/7 Ricarico Caddy e verifico"
  $SUDO systemctl reload caddy
  sleep 2
  for u in /chat/ /chat/js/main.js /chat/manifest.json /chat/katex/katex.min.js /chat/pdfjs/pdf.min.js /chat/pdflib/pdf-lib.min.js; do
    code=$(curl -s -o /dev/null -w '%{http_code}' "https://$HOST$u" || true)
    echo "   $u  ->  HTTP $code"
  done
  if [ "$FETCH_UP" = 1 ]; then
    code=$(curl -s -o /dev/null -w '%{http_code}' "https://$HOST/fetch/health" || true); echo "   /fetch/health  ->  HTTP $code"
    code=$(curl -s -o /dev/null -w '%{http_code}' -X POST -H 'Content-Type: application/json' -d '{"url":"https://example.com"}' "https://$HOST/fetch/" || true); echo "   /fetch/ senza accesso  ->  HTTP $code (atteso 401: serve il token)"
  fi
else
  echo "   (caddy non trovato: salto controllo e ricarica)"
fi
echo
echo "Fatto. Apri https://$HOST/chat/ (se vedi la versione vecchia, ricarica la pagina)."
